BEGIN
    EXECUTE IMMEDIATE 'DROP TRIGGER trg_gw_binding_key_hash_compat';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4080 THEN RAISE; END IF;
END;
/

DECLARE
    column_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO column_count FROM user_tab_columns
     WHERE table_name = 'GW_BINDING' AND column_name = 'BINDING_KEY_HASH';
    IF column_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE GW_BINDING ADD (binding_key_hash CHAR(64 CHAR))';
    END IF;
END;
/

DECLARE
    constraint_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO constraint_count FROM user_constraints
     WHERE table_name = 'GW_BINDING' AND constraint_name = 'UK_CPF_GWY_BINDING_KEY';
    IF constraint_count > 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE GW_BINDING DROP CONSTRAINT uk_cpf_gwy_binding_key';
    END IF;
END;
/

BEGIN
    EXECUTE IMMEDIATE 'DROP INDEX uq_gwy_binding_key';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1418 THEN RAISE; END IF;
END;
/

UPDATE GW_BINDING
   SET binding_key_hash = LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(
       LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(environment_code), ''), 'DEFAULT'), 'AL32UTF8'), 'SHA256'))) ||
       LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(host_pattern), ''), '*'), 'AL32UTF8'), 'SHA256'))) ||
       LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(TRIM(path_pattern), 'AL32UTF8'), 'SHA256'))) ||
       LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(http_method), ''), '*'), 'AL32UTF8'), 'SHA256'))) ||
       LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(api_version), ''), 'v1'), 'AL32UTF8'), 'SHA256'))) ||
       LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(NVL(NULLIF(TRIM(route_version), ''), '1'), 'AL32UTF8'), 'SHA256'))),
       'AL32UTF8'), 'SHA256')));

ALTER TABLE GW_BINDING MODIFY (binding_key_hash NOT NULL);
ALTER TABLE GW_BINDING ADD CONSTRAINT uk_cpf_gwy_binding_key UNIQUE (binding_key_hash);

DECLARE
    column_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO column_count FROM user_tab_columns
     WHERE table_name = 'CMN_RESPONSE_CODE' AND column_name = 'HTTP_STATUS';
    IF column_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE CMN_RESPONSE_CODE ADD (http_status NUMBER(10))';
    END IF;
END;
/

UPDATE CMN_RESPONSE_CODE
   SET http_status = CASE response_code
       WHEN 'SCPF000000' THEN 200
       WHEN 'ECPF010001' THEN 400
       WHEN 'ECPF010002' THEN 404
       WHEN 'ECPF010003' THEN 409
       WHEN 'ECPF010004' THEN 400
       WHEN 'ECPF010005' THEN 401
       WHEN 'ECPF010006' THEN 403
       WHEN 'ECPF020001' THEN 400
       WHEN 'ECPF030001' THEN 502
       WHEN 'ECPF900001' THEN 400
       WHEN 'ECPF900002' THEN 500
       WHEN 'ECPF900003' THEN 500
       WHEN 'ECPF900004' THEN 400
       WHEN 'ECPF900005' THEN 403
       WHEN 'ECPF990000' THEN 500
       WHEN 'ECPF990001' THEN 500
       WHEN 'SMBW000000' THEN 200
       WHEN 'EMBW010001' THEN 400
       WHEN 'EMBW010002' THEN 403
       WHEN 'EEDU010001' THEN 409
       WHEN 'ECPF030002' THEN 504
       WHEN 'ECPF030003' THEN 503
       WHEN 'ECPF030004' THEN 202
       WHEN 'ECPF020002' THEN 409
       WHEN 'ECPF020003' THEN 409
       WHEN 'ECPF040001' THEN 423
       WHEN 'ECPF040002' THEN 403
       WHEN 'ECPF020004' THEN 403
       WHEN 'ECPF020005' THEN 409
       WHEN 'ECPF020006' THEN 409
       WHEN 'ECPF020007' THEN 409
       WHEN 'ECPF040003' THEN 423
       WHEN 'ECPF040004' THEN 403
       WHEN 'ECPF050001' THEN 403
       WHEN 'ECPF050002' THEN 400
       ELSE CASE
           WHEN http_status BETWEEN 100 AND 599 THEN http_status
           WHEN result_type = 'S' THEN 200
           ELSE 500
       END
   END;
ALTER TABLE CMN_RESPONSE_CODE MODIFY (http_status NOT NULL);
